body:
The FVH still highlights if we use the ES Query_String_Query

```
    POST localhost:9200/testIndex/_search
    {
       "query": {
       "query_string": {
       "default_field": "fulltext.exact",
       "query": "\"significant parsing\"~4"
       }
   }, 
   "highlight": {
      "fields": {
         "fulltext.exact": {
            "type": "fvh",
            "number_of_fragments": 0
         }
      },
      "require_field_match": true
   }
}
```

However it is not supported when using the Span Query

```
POST localhost:9200/testIndex/_search
{
    "query": {
        "filtered": {
            "query": {
                "span_near": {
                    "clauses": [{
                        "span_term": {
                            "fulltext.exact": "significant"
                        }
                    }, {
                        "span_term": {
                            "fulltext.exact": "complexity"
                        }
                    }],
                    "slop": 4,
                    "in_order": false
                }
            },
            "filter": {
                "term": {
                    "documentid": "1de7343c6bdd400b936f76782db93065"
                }
            }
        }
    },
    "highlight": {
        "fields": {
            "fulltext.exact": {
                "matched_fields": ["fulltext.exact"],
                "type": "fvh",
                "number_of_fragments": 0
            }
        },
        "require_field_match": true
    }
}
```

As of 5.0, the `plain` highlighter works for all cases below, the `fvh` highlighter fails for out of order proximity queries and for all span queries.

Updated recreation:

```
PUT /twitter/

PUT /twitter/tweet/_mapping
{
  "properties": {
    "message": {
      "type": "text",
      "term_vector": "with_positions_offsets"
    }
  }
}

PUT /twitter/tweet/1
{
  "user": "kimchy",
  "post_date": "2009-11-15T14:12:12",
  "message": "trying out Elastic and Search"
}

PUT /twitter/tweet/2
{
  "user": "kimchy",
  "post_date": "2009-11-15T14:12:12",
  "message": "trying out Search and Elastic"
}

GET /twitter/tweet/_search
{
  "query": {
    "query_string": {
      "default_field": "message",
      "query": "\"Elastic Search\"~4"
    }
  },
  "highlight": {
    "fields": {
      "message": {
        "type": "fvh"
      }
    }
  }
}

POST /twitter/tweet/_search
{
  "query": {
    "span_near": {
      "clauses": [
        {
          "span_term": {
            "message": "search"
          }
        },
        {
          "span_term": {
            "message": "elastic"
          }
        }
      ],
      "slop": 4,
      "in_order": false
    }
  },
  "highlight": {
    "fields": {
      "message": {
        "type": "fvh"
      }
    }
  }
}
```
